mapper.select:
SELECT id, title, content_type, difficulty, content_body, status,
       version, created_at, updated_at
FROM training_content WHERE id = #{contentId}

mapper.update:
UPDATE training_content
SET title = #{title}, content_type = #{contentType}, difficulty = #{difficulty},
    content_body = #{contentBody}, status = #{status}, version = version + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND version = #{version}
